function timeText() { return `${String(Math.floor(remaining / 60)).padStart(2, '0')}:${String(remaining % 60).padStart(2, '0')}` }
function modal(content) { $('#modalcontent').innerHTML = content; if (!$('#modal').open) $('#modal').showModal() }
function openAdd(id) { refreshDay(); const existing = state.tasks.find(t => t.id === id), t = existing || { title: '', subject: '', date: page === 'tasks' ? selectedDate : todayISO }; modal(`<h2>${existing ? 'タスクを編集' : 'タスクを追加'}</h2><form id="addform"><label>やること<input name="title" required maxlength="80" value="${esc(t.title)}" placeholder="例：英語のレポートを書く"></label><label>授業・カテゴリー<input name="subject" maxlength="40" value="${esc(t.subject)}"></label><label>締切<input name="date" type="date" required value="${esc(t.date)}"></label><p id="taskError" role="alert"></p><button class="primary icon-btn" aria-label="タスクを保存">${icon('check')}</button></form>`); $('#addform').onsubmit = e => { e.preventDefault(); const f = new FormData(e.target), title = f.get('title').trim(), date = f.get('date'); if (!title || !/^\d{4}-\d{2}-\d{2}$/.test(date)) { $('#taskError').textContent = 'やることと締切を入力してください。'; return } const values = { title, subject: f.get('subject').trim() || '自分の目標', date }; if (existing) Object.assign(existing, values); else state.tasks.push({ id: Date.now(), ...values, done: false }); if (page === 'tasks') { selectedDate = date; month = new Date(date + 'T12:00:00'); month.setDate(1); taskPage = 0 } save(); $('#modal').close(); render(); toast(existing ? 'タスクを更新しました' : '新しい目標を植えました 🌱') } }
document.addEventListener('click', e => { const b = e.target.closest('button,a'); if (!b) return; if (b.id === 'retrySave') { if (save()) toast('保存しました'); return } if (b.id === 'dismissSaveError') { $('#toast').classList.remove('show'); return } refreshDay(); if (b.hasAttribute('data-task-next')) { taskPage += Number(b.dataset.taskNext); render() } if (b.id === 'clearFriendSearch') { friendQuery = ''; matchFilter = 'すべて'; friendDate = ''; friendTime = ''; onlyVacancies = false; render() } if (b.dataset.page) { taskPage = 0; taskFit = 5; if (running && state.settings.focusLock && b.dataset.page === 'collection') { toast('図鑑は集中が終わってからのお楽しみ。'); return } page = b.dataset.page; render(); window.scrollTo(0, 0) } if (b.dataset.friendView) { friendView = b.dataset.friendView; render() } if (b.dataset.meeting) openMeeting(Number(b.dataset.meeting)); if (b.dataset.person) openPerson(b.dataset.person); if (b.dataset.connect) { const key = b.dataset.connect; if (!people[key]) return; const added = !state.connections.includes(key); state.connections = added ? [...state.connections, key] : state.connections.filter(x => x !== key); save(); render(); openPerson(key); toast(added ? people[key].name + 'さんを仲間に追加しました' : '仲間から外しました') } if (b.id === 'goToday') { selectedDate = todayISO; month = new Date(today.getFullYear(), today.getMonth(), 1); taskPage = 0; render() } if (b.dataset.editTask) openAdd(Number(b.dataset.editTask)); if (b.dataset.deleteTask) openDeleteTask(Number(b.dataset.deleteTask)); if (b.dataset.confirmDeleteTask) deleteTask(Number(b.dataset.confirmDeleteTask)); if (b.id === 'editProfile') openProfileEditor(); if (b.id === 'openSettings') openSettings(); if (b.hasAttribute('data-add')) openAdd(); if (b.hasAttribute('data-recruit')) openRecruit(); if (b.dataset.editRecruit) openRecruit(Number(b.dataset.editRecruit)); if (b.dataset.endRecruit) confirmEndRecruit(Number(b.dataset.endRecruit)); if (b.dataset.confirmEndRecruit) endRecruit(Number(b.dataset.confirmEndRecruit)); if (b.dataset.month) { month.setMonth(month.getMonth() + Number(b.dataset.month)); render() } if (b.dataset.date) { selectedDate = b.dataset.date; taskPage = 0; taskFit = 5; render() } if (b.dataset.filter) { friendQuery = $('#friendQuery')?.value.trim() || ''; matchFilter = b.dataset.filter; render() } if (b.dataset.join) { toggleJoin(Number(b.dataset.join)); } if (b.dataset.duration && !running) { duration = Number(b.dataset.duration); state.duration = duration; remaining = duration * 60; deadline = null; sessionId = null; save(); render() } if (b.id === 'start') { if (running) { tickTimer(); if (!running) return; remaining = Math.max(0, Math.ceil((deadline - Date.now()) / 1000)); running = false; deadline = null; releaseWakeLock() } else { if (!applyMinutes()) return; running = true; if (!sessionId) { sessionId = 'focus-' + Date.now() + '-' + Math.random().toString(36).slice(2); sessionTask = focusTaskId() } deadline = Date.now() + remaining * 1000; prepareAlerts(); requestWakeLock() } save(); render() } if (b.id === 'reset') { running = false; deadline = null; remaining = duration * 60; sessionId = null; sessionTask = null; releaseWakeLock(); save(); render() } if (b.dataset.completeTask) { const t = state.tasks.find(t => t.id === Number(b.dataset.completeTask)); if (t) completeTask(t, true); $('#modal').close(); page = 'home'; render() } if (b.hasAttribute('data-harvest') && state.points >= 300) { state.points -= 300; state.rice += 3; save(); render(); modal('<h2>収穫できました！</h2><img class="result-art asset-img" src="assets/library/effect_harvest_success.webp" alt="収穫成功"><p>お米 +3カップ</p><button class="primary closemodal">また育てよう</button>') } if (b.matches('.close,.closemodal')) $('#modal').close(); });
document.addEventListener('change', e => { if (e.target.id === 'customMinutes') { applyMinutes(); return } if (e.target.id === 'friendDate') { friendDate = e.target.value; render() } if (e.target.id === 'friendTime') { friendTime = e.target.value; render() } if (e.target.id === 'onlyVacancies') { onlyVacancies = e.target.checked; render() } if (e.target.id === 'focusTask') { state.focusTaskId = e.target.value; save() } if (e.target.dataset.task) { const t = state.tasks.find(t => t.id === Number(e.target.dataset.task)); if (!t) { render(); return } completeTask(t, e.target.checked) } });
setInterval(() => { refreshDay(); tickTimer(); refreshMeetingStatus() }, 500);
initializePersistentData();
render();
tickTimer();
document.addEventListener('visibilitychange', () => { if (!document.hidden) { requestWakeLock(); refreshDay(); tickTimer(); refreshMeetingStatus() } });
window.addEventListener?.('focus', () => { refreshDay(); tickTimer(); refreshMeetingStatus() });

document.addEventListener('submit', e => { if (e.target.id === 'friendSearch') { e.preventDefault(); friendQuery = $('#friendQuery').value.trim(); render() } });

function openRecruit(id) {
  refreshDay(); const existing = state.recruitments.find(m => m.id === id); if (existing && meetingEnded(existing)) { openMeeting(id); return }
  const suggested = new Date(Date.now() + 3600000); suggested.setMinutes(0, 0, 0); const suggestedEnd = new Date(suggested.getTime() + 3600000); const nextDay = iso(suggestedEnd) !== iso(suggested); const m = existing || { title: '', type: '勉強', date: nextDay ? iso(suggestedEnd) : iso(suggested), start: nextDay ? '09:00' : suggested.toTimeString().slice(0, 5), end: nextDay ? '10:00' : suggestedEnd.toTimeString().slice(0, 5), place: '', capacity: 4 };
  modal(`<h2>${existing ? '募集を編集' : '仲間を募集する'}</h2><form id="recruitForm"><label>一緒にやること<input name="title" required maxlength="60" placeholder="例：統計学の課題を一緒に" value="${esc(m.title)}"></label><label>カテゴリー<select name="type">${friendCategories.map(t => `<option ${m.type === t ? 'selected' : ''}>${t}</option>`).join('')}</select></label><label>日付<input name="date" type="date" required min="${todayISO}" value="${esc(m.date)}"></label><div class="form-times"><label>開始<input type="time" name="start" required value="${esc(m.start)}"></label><label>終了<input type="time" name="end" required value="${esc(m.end)}"></label></div><label>場所<input name="place" required maxlength="50" placeholder="例：中央図書館 3F" value="${esc(m.place)}"></label><label>定員（自分を含む）<input name="capacity" type="number" min="2" max="20" required value="${m.capacity}"></label><p id="recruitError" role="alert"></p><button class="primary icon-btn" aria-label="募集を保存" title="保存">${icon('check')}</button></form>`);
  $('#recruitForm').onsubmit = e => {
    e.preventDefault(); refreshDay(); const f = new FormData(e.target), title = f.get('title').trim(), place = f.get('place').trim(), date = f.get('date'), start = f.get('start'), end = f.get('end'), capacity = Number(f.get('capacity'));
    let error = !/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}$/.test(start) || !/^\d{2}:\d{2}$/.test(end) ? '日付と開始・終了時間を入力してください。' : !title || !place ? 'やることと場所を入力してください。' : date < todayISO ? '今日以降の日付を選んでください。' : end <= start ? '終了は開始より後の時間を選んでください。' : new Date(date + 'T' + start).getTime() <= Date.now() ? 'これから開始する日時を選んでください。' : !Number.isInteger(capacity) || capacity < 2 || capacity > 20 ? '定員は2〜20人で入力してください。' : '';
    if (error) { $('#recruitError').textContent = error; return }
    const item = { ...existing, id: existing?.id || Date.now(), owned: true, title, type: f.get('type'), date, start, end, capacity, place, name: state.profile.name, time: date.replaceAll('-', '/') + ' ' + start + '–' + end };
    if (existing) state.recruitments = state.recruitments.map(r => r.id === id ? item : r); else state.recruitments.unshift(item);
    save(); friendView = 'discover'; friendDate = ''; friendTime = ''; friendQuery = ''; matchFilter = 'すべて'; $('#modal').close(); render(); toast(existing ? '募集を更新しました' : '募集を追加しました');
  };
}

function openProfileEditor() {
  const p = state.profile; modal(`<h2>プロフィールを編集</h2><form id="profileForm"><fieldset class="avatar-options"><legend>アイコン</legend>${[0, 1, 2, 3].map(n => `<label><input type="radio" name="avatar" value="${n}" ${p.avatar === n ? 'checked' : ''} aria-label="アイコン${n + 1}"><span class="avatar sprite s${n}"></span></label>`).join('')}</fieldset><label>名前<input name="name" maxlength="30" required value="${esc(p.name)}"></label><label>大学<input name="university" maxlength="60" required value="${esc(p.university)}"></label><label>学部・学科<input name="department" maxlength="60" value="${esc(p.department)}" placeholder="任意"></label><label>学年<select name="year">${['1年生', '2年生', '3年生', '4年生', '5年生', '6年生', '大学院生', 'その他'].map(y => `<option ${y === p.year ? 'selected' : ''}>${y}</option>`).join('')}</select></label><p class="form-error" id="profileError" role="alert"></p><button class="primary icon-btn" aria-label="プロフィールを保存" title="保存">${icon('check')}</button></form>`);
  $('#profileForm').onsubmit = e => { e.preventDefault(); const f = new FormData(e.target), name = f.get('name').trim(), university = f.get('university').trim(), avatar = Number(f.get('avatar')); if (!name || !university) { $('#profileError').textContent = '名前と大学を入力してください。'; return } if (![0, 1, 2, 3].includes(avatar)) return; state.profile = { name, university, department: f.get('department').trim(), year: f.get('year'), avatar }; state.recruitments = state.recruitments.map(m => m.owned ? { ...m, name } : m); save(); $('#modal').close(); render(); toast('プロフィールを保存しました') };
}
function openSettings() {
  modal(`<h2>設定</h2><form id="settingsForm"><label>集中時間（分）<input name="duration" type="number" min="1" max="180" step="1" required value="${duration}" ${running ? 'disabled' : ''}></label>${running ? '<p class="settings-hint">時間の変更は集中を一時停止してから</p>' : ''}<label class="switch-row"><span>集中中は図鑑をロック</span><input type="checkbox" name="focusLock" ${state.settings.focusLock ? 'checked' : ''}></label><label class="switch-row"><span>完了したタスクを隠す</span><input type="checkbox" name="hideCompleted" ${state.settings.hideCompleted ? 'checked' : ''}></label><p class="settings-hint">設定とプロフィールは、このブラウザに保存されます。</p><p class="form-error" id="settingsError" role="alert"></p><button class="primary icon-btn" aria-label="設定を保存" title="保存">${icon('check')}</button></form>`);
  $('#settingsForm').onsubmit = e => { e.preventDefault(); const f = new FormData(e.target), n = running ? duration : Number(f.get('duration')); if (!Number.isInteger(n) || n < 1 || n > 180) { $('#settingsError').textContent = '集中時間は1〜180分で入力してください。'; return } if (!running && n !== duration) { duration = n; remaining = n * 60; deadline = null; sessionId = null } state.duration = n; state.settings = { focusLock: f.get('focusLock') === 'on', hideCompleted: f.get('hideCompleted') === 'on' }; save(); $('#modal').close(); render(); toast('設定を保存しました') };
}

function completeTask(t, done) { t.done = done; if (t.done && !state.completedTaskIds.includes(t.id)) state.completedTaskIds.push(t.id); if (t.done && !t.rewarded) { state.points += 20; t.rewarded = true; toast('ひとつ達成！ 田んぼに +20 pt 🌱') } save(); render() }
function focusTaskId() { if (running && sessionTask !== null) return String(sessionTask); if (state.focusTaskId === '') return ''; const open = state.tasks.filter(t => !t.done); return String((open.find(t => String(t.id) === String(state.focusTaskId)) || open[0])?.id ?? '') }
function openDeleteTask(id) { const task = state.tasks.find(t => t.id === id); if (!task) return; modal(`<h2>タスクを削除しますか？</h2><p>${esc(task.title)}</p><div class="delete-actions"><button class="textbtn closemodal">やめる</button><button class="delete-confirm" data-confirm-delete-task="${id}">削除する</button></div>`) }
function deleteTask(id) { if (!state.tasks.some(t => t.id === id)) return; state.tasks = state.tasks.filter(t => t.id !== id); if (String(state.focusTaskId) === String(id)) delete state.focusTaskId; save(); $('#modal').close(); render(); toast('タスクを削除しました') }

function applyMinutes(editing = false) { if (running) return true; const input = $('#customMinutes'); if (!input) return true; const n = Number(input.value); if (!Number.isInteger(n) || n < 1 || n > 180) { if (editing) { $('#minuteError').textContent = ''; input.removeAttribute?.('aria-invalid'); return false } $('#minuteError').textContent = '1〜180分で入力してください'; input.setAttribute?.('aria-invalid', 'true'); return false } $('#minuteError').textContent = ''; input.removeAttribute?.('aria-invalid'); if (n !== duration) { duration = n; remaining = n * 60; deadline = null; sessionId = null; state.duration = n; save() } if ($('#time')) $('#time').textContent = timeText(); const reward = main.querySelector('.reward'); if (reward) reward.textContent = '完了で +' + duration * 2 + ' pt'; document.querySelectorAll?.('[data-duration]').forEach(b => b.classList.toggle('selected', Number(b.dataset.duration) === n)); return true }
function seedMeeting(s) { const t = seedTemplates.find(t => t.key === s.template); if (!t) return null; const host = people[t.host]; return { ...t, id: s.id, date: s.date, name: host.name, avatar: host.avatar, members: t.members.map(k => people[k].name) } }
function meetings() { return [...state.recruitments, ...(state.seedMeetings || []).map(seedMeeting).filter(Boolean)].map(m => ({ ...m, avatar: m.owned ? state.profile.avatar : m.avatar, members: m.members || [state.profile.name], time: m.date.replaceAll('-', '/') + ' ' + m.start + '–' + m.end })) }
function meetingCount(m) { return m.members.length + (state.joined.includes(m.id) ? 1 : 0) }
function filteredMeetings() {
  return meetings().filter(m => {
    if (friendView === 'history') return meetingEnded(m); if (meetingEnded(m)) return false; if (friendView === 'planned') return m.owned || state.joined.includes(m.id); if (meetingStarted(m)) return false;
    if (matchFilter !== 'すべて' && m.type !== matchFilter) return false;
    if (friendDate && m.date !== friendDate) return false;
    if (friendTime) { const ranges = { morning: ['00:00', '12:00'], afternoon: ['12:00', '18:00'], evening: ['18:00', '24:00'] }; const [start, end] = ranges[friendTime]; if (m.start >= end || m.end <= start) return false }
    if (onlyVacancies && meetingCount(m) >= m.capacity) return false;
    return !friendQuery || friendQuery.toLocaleLowerCase().normalize('NFKC').split(/\s+/).every(q => [m.title, m.type, m.name, m.place, m.time].join(' ').toLocaleLowerCase().normalize('NFKC').includes(q));
  })
}
function renderFriends() {
  let content = ''; if (friendView === 'people') { content = `<div class="matchlist">${state.connections.map(k => `<button class="card person-row" data-person="${k}"><span class="avatar sprite s${people[k].avatar}"></span><span><b>${esc(people[k].name)}</b><small>${esc(people[k].department)} · ${esc(people[k].year)}</small></span>${icon('right')}</button>`).join('') || '<div class="search-empty">募集のプロフィールから<br>仲間を追加できます。</div>'}</div>` } else { const list = filteredMeetings(); content = (friendView === 'discover' ? `<form class="friend-search" role="search" id="friendSearch"><input type="search" id="friendQuery" aria-label="課題・名前・場所で仲間を探す" placeholder="課題・名前・場所で探す" value="${esc(friendQuery)}"><button type="submit" class="primary icon-btn" aria-label="検索"><svg class="ui-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg></button></form><div class="friend-categories">${['すべて', ...friendCategories].map(f => `<button class="tab ${f === matchFilter ? 'selected' : ''}" aria-pressed="${f === matchFilter}" data-filter="${f}">${f}</button>`).join('')}</div><details class="filter-panel" ${friendDate || friendTime || onlyVacancies ? 'open' : ''}><summary>日時・空席で絞る${friendDate || friendTime || onlyVacancies ? ' · 設定中' : ''}</summary><div class="filter-fields"><label>日付<input id="friendDate" type="date" value="${friendDate}"></label><label>時間帯<select id="friendTime">${[['', 'いつでも'], ['morning', '午前'], ['afternoon', '午後'], ['evening', '夕方・夜']].map(([v, l]) => `<option value="${v}" ${friendTime === v ? 'selected' : ''}>${l}</option>`).join('')}</select></label></div><label class="vacancies"><input type="checkbox" id="onlyVacancies" ${onlyVacancies ? 'checked' : ''}>空席あり</label><button class="textbtn" id="clearFriendSearch">条件をクリア</button></details>` : '') + `<p class="search-count">${list.length}件${friendView === 'history' ? 'の履歴' : friendView === 'planned' ? 'の参加予定' : 'の募集'}</p><div class="matchlist" role="list" aria-label="仲間の募集">${list.map(m => `<article class="card match" role="listitem"><div class="match-copy"><span class="pill">${esc(m.type)}</span><button class="meeting-title" data-meeting="${m.id}"><h3>${esc(m.title)}</h3></button><p class="match-details"><span>${esc(m.time)}</span><span>${esc(m.place)}</span></p><div class="match-meta"><button class="match-host" ${m.owned ? 'data-page="profile"' : `data-person="${m.host}"`} aria-label="${esc(m.name)}のプロフィール"><span class="avatar sprite s${m.avatar}"></span>${esc(m.name)}</button><span>${meetingCount(m)} / ${m.capacity}人</span><span class="match-status">${meetingEnded(m) ? (m.closedAt ? '募集終了' : '終了済み') : m.owned ? '自分の募集' : state.joined.includes(m.id) ? '参加予定' : ''}</span></div></div><button class="textbtn icon-btn" data-meeting="${m.id}" aria-label="${esc(m.title)}の詳細">${icon('right')}</button></article>`).join('') || `<div class="search-empty">${art('empty_friends', 'empty-art', '')}<b>${friendView === 'history' ? '履歴はまだありません' : friendView === 'planned' ? '参加予定はまだありません' : '募集が見つかりませんでした'}</b><button class="textbtn" ${friendView === 'planned' ? 'data-friend-view="discover"' : 'id="clearFriendSearch"'}>${friendView === 'planned' ? '仲間をさがす' : '条件をクリア'}</button></div>`}</div>` }
  return head('仲間をさがそう <button class="textbtn icon-btn new-recruit" data-recruit aria-label="仲間を募集する">' + icon('plus') + '</button>') + `<div class="friend-views">${[['discover', 'さがす'], ['planned', '参加予定'], ['people', '仲間'], ['history', '履歴']].map(([v, l]) => `<button data-friend-view="${v}" aria-pressed="${friendView === v}" class="${friendView === v ? 'selected' : ''}">${l}</button>`).join('')}</div>` + content
}
function openMeeting(id) { const m = meetings().find(m => m.id === id); if (!m) return; const joined = state.joined.includes(id); modal(`<div class="meeting-detail" data-meeting-id="${id}"><span class="pill">${esc(m.type)}</span><h2>${esc(m.title)}</h2><dl><dt>日時</dt><dd>${esc(m.time)}</dd><dt>集合場所</dt><dd>${esc(m.place)}</dd><dt>メンバー · ${meetingCount(m)} / ${m.capacity}人</dt><dd>${m.members.map(n => `<span class="member-chip">${esc(n)}</span>`).join('')}${joined ? `<span class="member-chip">${esc(state.profile.name)}（あなた）</span>` : ''}</dd></dl>${!m.owned ? `<button class="person-link" data-person="${m.host}"><span class="avatar sprite s${m.avatar}"></span>${esc(m.name)}のプロフィール ${icon('right')}</button><button class="primary meeting-join" data-join="${id}" ${meetingStarted(m) ? 'disabled' : ''} ${!joined && meetingCount(m) >= m.capacity ? 'disabled' : ''}>${meetingEnded(m) ? (m.closedAt ? '募集終了' : '終了済み') : meetingStarted(m) ? '開始済み' : joined ? '参加を取り消す' : meetingCount(m) >= m.capacity ? '満員' : '参加する'}</button>` : `<p class="meeting-state">${meetingEnded(m) ? (m.closedAt ? '募集終了' : '終了済み') : ''}</p>${!meetingEnded(m) ? `<button class="primary meeting-join" data-edit-recruit="${id}">募集を編集する</button><button class="end-recruit" data-end-recruit="${id}">募集を終了する</button>` : ''}`}</div>`) }
function openPerson(key) { const p = people[key]; if (!p) return; const connected = state.connections.includes(key); const next = meetings().filter(m => m.host === key && !meetingEnded(m)).sort((a, b) => (a.date + a.start).localeCompare(b.date + b.start))[0]; modal(`<div class="person-detail"><span class="avatar sprite s${p.avatar}"></span><h2>${esc(p.name)}</h2><p>${esc(p.department)} · ${esc(p.year)}</p><button class="primary meeting-join" data-connect="${key}" aria-pressed="${connected}">${connected ? '仲間から外す' : '仲間に追加する'}</button>${next ? `<button class="textbtn" data-meeting="${next.id}">募集を見る</button>` : ''}</div>`) }
function toggleJoin(id) { const m = meetings().find(m => m.id === id && !m.owned); if (!m) return; if (meetingStarted(m)) { openMeeting(id); return } const joined = state.joined.includes(id); if (!joined && meetingCount(m) >= m.capacity) { toast('この募集は満員です'); return } state.joined = joined ? state.joined.filter(x => x !== id) : [...state.joined, id]; save(); render(); openMeeting(id); toast(joined ? '参加予定を取り消しました' : '参加予定に追加しました') }

document.addEventListener('input', e => { if (e.target.id === 'customMinutes') applyMinutes(true) });

function navIcon(name) { if (name === 'profile') return `<span class="nav-art nav-face avatar sprite s${state.profile.avatar}" aria-hidden="true"></span>`; const assets = { home: 'paddy_4_plots', tasks: 'calendar', friends: 'students_group_02', focus: 'clock' }; return art(assets[name], 'nav-art nav-' + name, '') }

function initializePersistentData() {
  let changed = false;
  if (!Array.isArray(state.seedMeetings)) state.seedMeetings = []; if (replenishSeeds()) changed = true;
  restoreTimer();
  if (changed) save();
  meetingStatusKey = meetingStatus();

  fetchCampusWeather();
}
