function stage(){return state.points>=300?'収穫のとき':state.points>=200?'実りの時期':state.points>=100?'すくすく期':'田植えの時期'}
function farm(){const level=Math.min(6,Math.floor(state.points/60)+1);const rice='rice_stage_0'+level;const places=[[50,27],[44,32],[56,33],[25,46],[20,51],[31,52],[73,46],[68,51],[79,52],[49,65],[43,70],[55,71]];const sky=skyKind(),w=freshWeather();return `<div class="farmart supplied-field sky-${sky}" role="img" aria-label="${stage()}の田んぼ"><div class="field-land"></div>${w?`<span class="weather-chip">SFC ${weatherLabel(w.code)} ${w.temp}℃</span>`:''}${sky==='clear'&&(!w||w.code<=1)?art('sun','field-sun'):''}${art('mountain','field-mountain')}${art('hill','field-hill')}${art('university','field-university')}${art('tree','field-tree')}<div class="paddy-scene">${art('paddy_4_plots','field-paddy')}${places.map(([x,y])=>`<img class="field-rice" src="${suppliedAssets[rice]}" alt="" style="left:${x}%;top:${y}%">`).join('')}</div>${art('students_study_02','field-students')}${art('rice_mascot_normal','field-mascot')}${art('bush','field-bush')}${art('flower','field-flower')}</div>`}
function farmFriends(){const list=state.connections.map(k=>people[k]);if(!list.length)return `<button class="farm-friends empty" data-page="friends" aria-label="仲間をさがす">${art('students_group_02','farm-friends-art','')}<span>仲間と一緒に育てよう</span>${icon('right')}</button>`;return `<button class="farm-friends" data-friend-view="people" data-page="friends" aria-label="一緒に育てる仲間"><span class="farm-faces">${list.slice(0,3).map(p=>`<span class="avatar sprite s${p.avatar}"></span>`).join('')}</span><span class="farm-friends-text">${list.slice(0,2).map(p=>esc(p.name)).join('・')}${list.length>2?` ほか${list.length-2}人`:''}と育て中</span>${state.togetherPoints?`<span class="farm-together">+${state.togetherPoints}pt</span>`:''}${icon('right')}</button>`}
function head(title){return `<div class="heading"><div><h1>${title}</h1></div><span class="date">${today.toLocaleDateString('ja-JP',{month:'long',day:'numeric',weekday:'long'})}</span></div>`}
function taskRows(tasks,expanded=false){
 const complete=tasks.length&&tasks.every(t=>t.done);
 if(page==='home'&&complete&&!expanded)return `<div class="all-done">${art('task_complete','','')}<strong>今日のタスク完了！</strong></div><details class="completed-tasks"><summary>完了したタスクを見る</summary>${taskRows(tasks,true)}</details>`;
 if(state.settings.hideCompleted&&!expanded)tasks=tasks.filter(t=>!t.done);
 tasks=[...tasks].sort((a,b)=>Number(a.done)-Number(b.done)||a.date.localeCompare(b.date));
 const size=expanded?tasks.length:page==='home'?homeFit:taskFit;
 taskPage=Math.max(0,Math.min(taskPage,Math.ceil(tasks.length/size)-1));
 return tasks.length?tasks.slice(taskPage*size,(taskPage+1)*size).map(t=>`<div class="task ${t.done?'done':''}"><input type="checkbox" aria-label="${esc(t.title)}を完了" data-task="${t.id}" ${t.done?'checked':''}><div><button class="task-title" data-edit-task="${t.id}" aria-label="${esc(t.title)}を編集"><strong>${esc(t.title)}</strong><span class="task-edit-hint">${icon('edit')}</span></button><small>${esc(t.subject)}${t.focusMinutes?` · 集中 ${t.focusMinutes}分`:''}</small></div><span class="tag ${!t.done&&t.date<=todayISO?'urgent':''}">${t.done?'完了':t.date<todayISO?'期限超過':t.date===todayISO?'今日まで':'予定'}</span>${page==='tasks'?`<button class="task-delete" data-delete-task="${t.id}" aria-label="${esc(t.title)}を削除" title="タスクを削除">${icon('trash')}</button>`:''}</div>`).join('')+(tasks.length>size?`<div class="pager"><button aria-label="前のタスク" data-task-next="-1" ${taskPage===0?'disabled':''}>‹</button><span>${taskPage+1} / ${Math.ceil(tasks.length/size)}</span><button aria-label="次のタスク" data-task-next="1" ${(taskPage+1)*size>=tasks.length?'disabled':''}>›</button></div>`:''):'<div class="empty">表示するタスクはありません。</div>';
}
function render(){if(page==='focus'){page='friends';friendView='rooms'}document.body.dataset.page=page;document.body.dataset.sky=skyKind(); $('#nav').innerHTML=menus.map(([p,l])=>`<button data-page="${p}" class="${(page===p||(p==='profile'&&page==='collection'))?'active':''}" aria-label="${l}" title="${l}" ${(page===p||(p==='profile'&&page==='collection'))?'aria-current="page"':''}>${navIcon(p)}</button>`).join('');if(page==='home'){main.innerHTML=head('みんなで育てよう')+`<div class="grid"><section class="card farm">${farm()}<div class="farmbottom"><div class="between"><b>${stage()}</b><span class="subtle">${state.points} / 300 pt</span></div><div class="progress"><div style="width:${Math.min(100,state.points/3)}%"></div></div>${farmFriends()}${state.points>=300?'<button class="primary" data-harvest style="margin-top:15px;width:100%">実りを収穫する</button>':''}</div></section>${quickFocus()}</div><div class="grid lowgrid"><section class="card"><div class="between"><h2 class="sectiontitle">今日のタスク <span class="taskcount">${homeTasks().filter(t=>t.done).length} / ${homeTasks().length}</span></h2><button class="textbtn icon-btn" data-add aria-label="タスクを追加" title="タスクを追加">${icon('plus')}</button></div>${taskRows(homeTasks())}</section></div>`}else if(page==='tasks'){main.innerHTML=head('今日のやることを見つけよう')+`<div class="grid"><section class="card"><div class="between"><button class="textbtn icon-btn" data-month="-1" aria-label="前月" title="前月">${icon('left')}</button><div class="month-heading"><h2 class="sectiontitle">${month.getFullYear()}年 ${month.getMonth()+1}月</h2><button class="textbtn" id="goToday">今日へ戻る</button></div><button class="textbtn icon-btn" data-month="1" aria-label="翌月" title="翌月">${icon('right')}</button></div><div class="calendar">${['月','火','水','木','金','土','日'].map(x=>`<div class="week">${x}</div>`).join('')}${calendar()}</div></section><section class="card"><div class="between"><h2 class="sectiontitle">${selectedDate.slice(5).replace('-','月')}日のタスク</h2><button class="textbtn icon-btn" data-add aria-label="タスクを追加" title="タスクを追加">${icon('plus')}</button></div>${taskRows(state.tasks.filter(t=>t.date===selectedDate))}</section></div>`}else if(page==='friends'){main.innerHTML=renderFriends();}else if(page==='collection'){main.innerHTML=head('実りをあつめよう <button class="textbtn icon-btn back-profile" data-page="profile" aria-label="マイページに戻る" title="戻る">'+icon('left')+'</button>')+`<section class="card"><div class="between"><div><h2 class="harvest-heading"><span>収穫したお米</span><span class="harvest-amount">${state.rice}<small>カップ</small></span></h2><p class="subtle">300 pt → お米3カップ</p></div><button class="primary" data-harvest ${state.points<300?'disabled':''}>${state.points>=300?'収穫する':'あと '+(300-state.points)+' pt'}</button></div><div class="progress"><div style="width:${Math.min(100,state.points/3)}%"></div></div>${collectRate()}<div class="collect">${dishes.map(([n,r])=>`<article>${state.rice<r?`<span class="food-lock" aria-label="未解放">${icon('lock')}</span>`:''}<div class="food-art sprite s${r===3?8:r===6?9:10} ${state.rice>=r?'':'locked'}" role="img" aria-label="${n}"></div><b>${n}</b><p>${state.rice>=r?'解放済み':r+'カップ<br>収穫で解放'}</p></article>`).join('')}</div></section>`}else{main.innerHTML=`<section class="card profile-card"><div class="profile-identity"><span class="avatar sprite s${state.profile.avatar}" role="img" aria-label="プロフィールアイコン"></span><div><h2>${esc(state.profile.name)}</h2><p>${esc(state.profile.university)} · ${esc(state.profile.year)}</p>${state.profile.department?`<p>${esc(state.profile.department)}</p>`:''}</div><button class="textbtn icon-btn" id="editProfile" aria-label="プロフィールを編集" title="プロフィールを編集">${icon('edit')}</button></div><p class="stats-label">累計</p><div class="stats"><div><strong>${state.minutes}<small>分</small></strong><span>集中時間</span></div><div><strong>${state.completedTaskIds.length}</strong><span>完了したタスク</span></div><div><strong>${new Set(state.roomHistory.flatMap(h=>h.with)).size}<small>人</small></strong><span>いっしょに集中</span></div></div><button class="profile-collection" data-page="collection">${art('rice_bundle','collection-entry-art','')}<span><b>収穫・図鑑</b><small>お米 ${state.rice} カップ · 図鑑 ${dishes.filter(([,r])=>state.rice>=r).length} / ${dishes.length}</small></span>${icon('right')}</button><button class="profile-settings" id="openSettings">${icon('settings')}<span>設定</span>${icon('right')}</button></section>`}fitTasks()}
// 画面に収まらない分は次のページへ送る（スクロールなしのレイアウトでページ送りが隠れないように）
function fitTasks(){if(page==='home'){const f=$('.farm');if(f&&homeFit>1&&(f.getBoundingClientRect().height<innerHeight*.47||main.scrollHeight>main.clientHeight+1)){homeFit--;render()}return}if(page!=='tasks'||getComputedStyle(main).overflowY!=='hidden')return;if(taskFit>1&&main.scrollHeight>main.clientHeight+1){taskFit--;render()}}
window.addEventListener?.('resize',()=>{clearTimeout(window.fitTimer);window.fitTimer=setTimeout(()=>{taskFit=5;homeFit=4;render()},150)});

function calendar(){let h='',offset=(month.getDay()+6)%7;for(let i=0;i<offset;i++)h+='<div></div>';for(let d=1;d<=new Date(month.getFullYear(),month.getMonth()+1,0).getDate();d++){let dt=iso(new Date(month.getFullYear(),month.getMonth(),d)),n=state.tasks.filter(t=>t.date===dt).length;h+=`<button class="day ${selectedDate===dt?'chosen':''} ${dt===todayISO?'is-today':''}" aria-label="${dt}${dt===todayISO?' 今日':''}${n?' '+n+'件':''}" aria-pressed="${selectedDate===dt}" data-date="${dt}">${d}${n?'<i class="day-dot" aria-hidden="true"></i>':''}</button>`}return h}
function timeText(){return `${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`}
function modal(content){$('#modalcontent').innerHTML=content;if(!$('#modal').open)$('#modal').showModal()}
function openAdd(id){refreshDay();const existing=state.tasks.find(t=>t.id===id),t=existing||{title:'',subject:'',date:page==='tasks'?selectedDate:todayISO};modal(`<h2>${existing?'タスクを編集':'タスクを追加'}</h2><form id="addform"><label>やること<input name="title" required maxlength="80" value="${esc(t.title)}" placeholder="例：英語のレポートを書く"></label><label>授業・カテゴリー<input name="subject" maxlength="40" value="${esc(t.subject)}"></label><label>締切<input name="date" type="date" required value="${esc(t.date)}"></label><p id="taskError" role="alert"></p><button class="primary icon-btn" aria-label="タスクを保存">${icon('check')}</button></form>`);$('#addform').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),title=f.get('title').trim(),date=f.get('date');if(!title||!/^\d{4}-\d{2}-\d{2}$/.test(date)){$('#taskError').textContent='やることと締切を入力してください。';return}const values={title,subject:f.get('subject').trim()||'自分の目標',date};if(existing){Object.assign(existing,values);delete existing.demo}else state.tasks.push({id:Date.now(),...values,done:false});if(page==='tasks'){selectedDate=date;month=new Date(date+'T12:00:00');month.setDate(1);taskPage=0}save();$('#modal').close();render();toast(existing?'タスクを更新しました':'新しい目標を植えました',existing?'':'rice_stage_02')}}
document.addEventListener('click',e=>{const card=e.target.closest('[data-go-rooms]');if(card&&!e.target.closest('button')){page='friends';friendView='rooms';taskPage=0;render();return}const b=e.target.closest('button,a');if(!b)return;if(b.id==='retrySave'){if(save())toast('保存しました');return}if(b.id==='dismissSaveError'){$('#toast').classList.remove('show');return}refreshDay();if(b.hasAttribute('data-task-next')){taskPage+=Number(b.dataset.taskNext);render()}if(b.dataset.page){taskPage=0;taskFit=5;homeFit=4;page=b.dataset.page;render();window.scrollTo(0,0)}if(b.dataset.friendView){friendView=b.dataset.friendView;render()}if(b.dataset.mapPerson){mapSelected=b.dataset.mapPerson;if(b.hasAttribute('data-close-modal'))$('#modal').close();render()}if(b.dataset.mapHistory)openTogetherHistory(b.dataset.mapHistory);if(b.hasAttribute('data-map-more'))openMapList();if(b.dataset.person)openPerson(b.dataset.person);if(b.dataset.connect){const key=b.dataset.connect;if(!people[key])return;const added=!state.connections.includes(key);state.connections=added?[...state.connections,key]:state.connections.filter(x=>x!==key);save();render();openPerson(key);toast(added?people[key].name+'さんを仲間に追加しました':'仲間から外しました')}if(b.id==='goToday'){selectedDate=todayISO;month=new Date(today.getFullYear(),today.getMonth(),1);taskPage=0;render()}if(b.dataset.editTask)openAdd(Number(b.dataset.editTask));if(b.dataset.deleteTask)openDeleteTask(Number(b.dataset.deleteTask));if(b.dataset.confirmDeleteTask)deleteTask(Number(b.dataset.confirmDeleteTask));if(b.id==='editProfile')openProfileEditor();if(b.id==='openSettings')openSettings();if(b.hasAttribute('data-reset-data'))modal(`<h2>最初からやり直しますか？</h2><p>タスク・ポイント・仲間・履歴がすべて消えます。元には戻せません。</p><div class="delete-actions"><button class="textbtn closemodal">やめる</button><button class="delete-confirm" data-confirm-reset>やり直す</button></div>`);if(b.hasAttribute('data-confirm-reset')){try{localStorage.removeItem('tanboru-v1')}catch{}location.reload();return}if(b.hasAttribute('data-add'))openAdd();if(b.dataset.month){month.setMonth(month.getMonth()+Number(b.dataset.month));render()}if(b.dataset.date){selectedDate=b.dataset.date;taskPage=0;taskFit=5;render()}if(b.dataset.roomDuration&&!running){customTime=false;setDuration(Number(b.dataset.roomDuration));render()}if(b.hasAttribute('data-room-custom')){customTime=true;render();$('#roomMinutes')?.focus();$('#roomMinutes')?.select()}if(b.hasAttribute('data-arrived')&&state.room&&!state.room.arrived){state.room.arrived=true;save();render();toast(people[state.room.host].name+'さんに着いたことを知らせました','rice_mascot_happy')}if(b.hasAttribute('data-open-room'))openOwnRoom();if(b.dataset.room)openRoom(b.dataset.room);if(b.dataset.joinRoom)joinRoom(b.dataset.joinRoom);if(b.hasAttribute('data-leave-room'))modal(`<h2>作業場を出ますか？</h2><p>${focusedMinutes()>=1?`ここまでの${focusedMinutes()}分は、半分の +${focusedMinutes()} pt になります。`:'まだ1分たっていないので、ポイントはつきません。'}</p><div class="delete-actions"><button class="textbtn closemodal">やめる</button><button class="delete-confirm" data-confirm-leave>出る</button></div>`);if(b.hasAttribute('data-confirm-leave'))leaveRoom();if(b.dataset.stamp&&state.room){const names=roomMembers(state.room).map(o=>people[o[0]].name);toast(`${names.join('・')}さんに「${b.dataset.stamp}」を送りました`,'rice_mascot_happy');if(!state.room.replied){state.room.replied=true;save();const k=roomMembers(state.room)[0][0];setTimeout(()=>{if(state.room)toast(`${people[k].name}さんから「${b.dataset.stamp==='おつかれ'?'おつかれ':'がんばろう'}」`,'rice_mascot_happy')},2600)}}if(b.dataset.cheer&&people[b.dataset.cheer])toast(people[b.dataset.cheer].name+'さんに拍手を送りました','rice_mascot_happy');if(b.dataset.befriend){const key=b.dataset.befriend;if(people[key]&&!state.connections.includes(key)){state.connections=[...state.connections,key];save();render();b.classList.add('done');b.disabled=true;b.setAttribute('aria-label',people[key].name+'さんと仲間になりました');b.querySelector('.befriend-badge').innerHTML=icon('check');toast(people[key].name+'さんと仲間になりました','rice_mascot_happy')}return}if(b.dataset.completeTask){const t=state.tasks.find(t=>t.id===Number(b.dataset.completeTask));if(t)completeTask(t,true);$('#modal').close();page='home';render()}if(b.hasAttribute('data-harvest')&&state.points>=300){state.points-=300;state.rice+=3;save();render();modal('<h2>収穫できました！</h2><img class="result-art asset-img" src="assets/library/effect_harvest_success.webp" alt="収穫成功"><p>お米 +3カップ</p><button class="primary closemodal" data-page="collection">図鑑で料理を見る</button><button class="textbtn closemodal">また育てよう</button>')}if(b.matches('.close,.closemodal'))$('#modal').close();});
document.addEventListener('change',e=>{if(e.target.id==='roomMinutes'){const n=Number(e.target.value);if(!Number.isInteger(n)||n<1||n>180){toast('1〜180分で入力してください');e.target.value=duration;return}setDuration(n);render();return}if(e.target.id==='roomTask'){state.focusTaskId=e.target.value;save()}if(e.target.id==='roomPlace'){state.roomPlace=e.target.value;save();render()}if(e.target.id==='roomMark'){state.roomMark=e.target.value.trim().slice(0,30);save()}if(e.target.dataset.task){const t=state.tasks.find(t=>t.id===Number(e.target.dataset.task));if(!t){render();return}completeTask(t,e.target.checked)}});
setInterval(()=>{refreshDay();tickTimer();refreshRooms();refreshSky()},500);
initializePersistentData();
render();
tickTimer();
document.addEventListener('visibilitychange',()=>{if(!document.hidden){fetchWeather();requestWakeLock();refreshDay();tickTimer()}});
window.addEventListener?.('focus',()=>{refreshDay();tickTimer()});



function openProfileEditor(){const p=state.profile;modal(`<h2>プロフィールを編集</h2><form id="profileForm"><fieldset class="avatar-options"><legend>アイコン</legend>${[0,1,2,3].map(n=>`<label><input type="radio" name="avatar" value="${n}" ${p.avatar===n?'checked':''} aria-label="アイコン${n+1}"><span class="avatar sprite s${n}"></span></label>`).join('')}</fieldset><label>名前<input name="name" maxlength="30" required value="${esc(p.name)}"></label><label>大学<input name="university" maxlength="60" required value="${esc(p.university)}"></label><label>学部<select name="department">${['','総合政策学部','環境情報学部','看護医療学部'].map(d=>`<option value="${d}" ${p.department===d?'selected':''}>${d||'選ばない'}</option>`).join('')}${p.department&&!['総合政策学部','環境情報学部','看護医療学部'].includes(p.department)?`<option selected>${esc(p.department)}</option>`:''}</select></label><label>学年<select name="year">${['1年生','2年生','3年生','4年生','5年生','6年生','大学院生','その他'].map(y=>`<option ${y===p.year?'selected':''}>${y}</option>`).join('')}</select></label><p class="form-error" id="profileError" role="alert"></p><button class="primary icon-btn" aria-label="プロフィールを保存" title="保存">${icon('check')}</button></form>`);
$('#profileForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=f.get('name').trim(),university=f.get('university').trim(),avatar=Number(f.get('avatar'));if(!name||!university){$('#profileError').textContent='名前と大学を入力してください。';return}if(![0,1,2,3].includes(avatar))return;state.profile={name,university,department:f.get('department').trim(),year:f.get('year'),avatar};save();$('#modal').close();render();toast('プロフィールを保存しました')};}
function openSettings(){const st=state.settings,times=[...new Set([15,25,50,duration])].sort((a,b)=>a-b);modal(`<h2>設定</h2><form id="settingsForm"><p class="settings-group">作業場</p><label>よく使う場所<select name="place">${[...sfcPlaces,ONLINE].map(x=>`<option ${state.roomPlace===x?'selected':''}>${x}</option>`).join('')}</select></label><label>いつもの集中時間<select name="duration">${times.map(n=>`<option value="${n}" ${duration===n?'selected':''}>${n}分</option>`).join('')}</select></label><p class="settings-group">終わりの合図</p><label class="switch-row"><span>振動</span><input type="checkbox" name="vibrate" ${st.vibrate?'checked':''}></label><label class="switch-row"><span>音<small>図書館などでは切っておくと安心</small></span><input type="checkbox" name="sound" ${st.sound?'checked':''}></label><label class="switch-row"><span>画面を閉じていても通知</span><input type="checkbox" name="notify" ${st.notify?'checked':''}></label><p class="settings-group">タスク</p><label class="switch-row"><span>完了したタスクを隠す</span><input type="checkbox" name="hideCompleted" ${st.hideCompleted?'checked':''}></label><button class="primary icon-btn" aria-label="設定を保存" title="保存">${icon('check')}</button></form><p class="settings-hint">データはこのスマホにだけ保存されます。</p><button class="textbtn settings-reset" data-reset-data>最初からやり直す</button>`);
$('#settingsForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);let notify=f.get('notify')==='on';if(notify&&'Notification' in window&&Notification.permission==='default'){try{await Notification.requestPermission()}catch{}}if(notify&&(!('Notification' in window)||Notification.permission!=='granted')){notify=false;toast('通知が許可されていません。端末の設定から変更できます')}else toast('設定を保存しました');state.settings={hideCompleted:f.get('hideCompleted')==='on',vibrate:f.get('vibrate')==='on',sound:f.get('sound')==='on',notify};if([...sfcPlaces,ONLINE].includes(f.get('place')))state.roomPlace=f.get('place');const n=Number(f.get('duration'));if(Number.isInteger(n)&&n>=1&&n<=180)setDuration(n);save();$('#modal').close();render()};}

function completeTask(t,done){t.done=done;if(t.done&&!state.completedTaskIds.includes(t.id))state.completedTaskIds.push(t.id);if(t.done&&!t.rewarded){state.points+=20;t.rewarded=true;toast('ひとつ達成！ 田んぼに +20 pt','rice_stage_04')}save();render()}
function focusTaskId(){if(running&&sessionTask!==null)return String(sessionTask);if(state.focusTaskId==='')return '';const open=state.tasks.filter(t=>!t.done);return String((open.find(t=>String(t.id)===String(state.focusTaskId))||open[0])?.id??'')}
function openDeleteTask(id){const task=state.tasks.find(t=>t.id===id);if(!task)return;modal(`<h2>タスクを削除しますか？</h2><p>${esc(task.title)}</p><div class="delete-actions"><button class="textbtn closemodal">やめる</button><button class="delete-confirm" data-confirm-delete-task="${id}">削除する</button></div>`)}
function deleteTask(id){if(!state.tasks.some(t=>t.id===id))return;state.tasks=state.tasks.filter(t=>t.id!==id);if(String(state.focusTaskId)===String(id))delete state.focusTaskId;save();$('#modal').close();render();toast('タスクを削除しました')}

function setDuration(n){duration=n;state.duration=n;if(!running){remaining=n*60;deadline=null;sessionId=null}save()}
function renderFriends(){if(friendView!=='rooms')friendView='people';const content=friendView==='people'?renderMap():renderRooms();
return head(friendView==='rooms'?'いっしょに集中しよう':'仲間とつながろう')+`<div class="friend-views">${[['rooms','作業場'],['people','仲間']].map(([v,l])=>`<button data-friend-view="${v}" aria-pressed="${friendView===v}" class="${friendView===v?'selected':''}">${l}</button>`).join('')}</div>`+content}
function openPerson(key){const p=people[key];if(!p)return;const connected=state.connections.includes(key);modal(`<div class="person-detail"><span class="avatar sprite s${p.avatar}"></span><h2>${esc(p.name)}</h2><p>${esc(p.department)} · ${esc(p.year)}</p><button class="primary meeting-join" data-connect="${key}" aria-pressed="${connected}">${connected?'仲間から外す':'仲間に追加する'}</button>${roomOf(key)&&!running?`<button class="textbtn" data-room="${roomOf(key).key}">作業場を見る</button>`:''}</div>`)}


function navIcon(name){if(name==='profile')return `<span class="nav-art nav-face avatar sprite s${state.profile.avatar}" aria-hidden="true"></span>`;const assets={home:'paddy_4_plots',tasks:'calendar',friends:'students_group_02'};return art(assets[name],'nav-art nav-'+name,'')}

function initializePersistentData(){
 let changed=false;
 restoreTimer();
 if(changed)save();
}
function restoreTimer(){const t=state.timer;if(t&&Number.isInteger(t.duration)&&t.duration>=1&&t.duration<=180){duration=t.duration;remaining=Number.isFinite(t.remaining)?Math.max(0,Math.min(t.remaining,duration*60)):duration*60;running=!!t.running&&Number.isFinite(t.deadline);deadline=running?t.deadline:null;sessionId=t.sessionId||null;sessionTask=t.sessionTask??null;if(running)remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000))}if(running&&!state.room)state.room={mine:true,host:'me',title:'自由に集中',type:'勉強',endAt:deadline,joinedAt:deadline-duration*60000,joinAt:deadline+1};if(!running)state.room=null}
// 別のタブで変更されたら、こちらの表示も最新にする
window.addEventListener?.('storage',e=>{if(e.key!=='tanboru-v1'||!e.newValue)return;try{state=JSON.parse(e.newValue)}catch{return}normalizeState();restoreTimer();render()});
function refreshDay(){const now=new Date(),next=iso(now);if(next===todayISO)return false;const previous=todayISO;today=now;todayISO=next;state.tasks.forEach(t=>{if(t.demo)t.date=next});save();if(selectedDate===previous){selectedDate=next;month=new Date(now.getFullYear(),now.getMonth(),1)}taskPage=0;render();return true}
function tickTimer(){if(!running)return;remaining=Math.max(0,Math.ceil((deadline-Date.now())/1000));if($('#time'))$('#time').textContent=timeText();if($('#quicktime'))$('#quicktime').textContent=timeText();if(remaining>0){roomTick();return}const room=state.room,others=room?roomMembers(room):[],earned=room?Math.max(1,Math.round((room.endAt-room.joinedAt)/60000)):duration,bonus=others.length?10:0,task=state.tasks.find(t=>String(t.id)===String(sessionTask));running=false;deadline=null;remaining=duration*60;if(!sessionId||state.lastCompletedSession!==sessionId){state.points+=earned*2+bonus;if(others.length)state.togetherPoints+=earned*2+bonus;state.minutes+=earned;state.sessions++;state.lastCompletedSession=sessionId;if(task)task.focusMinutes=(task.focusMinutes||0)+earned;state.recentTogether=[...new Set([...others.map(o=>o[0]),...state.recentTogether])].slice(0,6);state.roomHistory=[{at:Date.now(),place:room?.place||'',minutes:earned,task:task?.title||'',with:others.map(o=>o[0])},...state.roomHistory].slice(0,20)}sessionId=null;sessionTask=null;state.room=null;releaseWakeLock();save();render();alertDone(earned,task);const newFriends=others.map(o=>o[0]).filter(k=>!state.connections.includes(k));modal(`<h2>${others.length?`みんなで${earned}分、やりきった！`:`${earned}分間、おつかれさま！`}</h2>${others.length&&!newFriends.length?`<div class="done-faces">${['me',...others.map(o=>o[0])].map(k=>`<span class="avatar sprite s${k==='me'?state.profile.avatar:people[k].avatar}"></span>`).join('')}</div>`:`<img class="result-art asset-img" src="assets/library/focus_complete.webp" alt="集中完了">`}${task?`<p class="focus-result-task">${esc(task.title)}</p>`:''}<p class="done-points">+${earned*2+bonus} pt${bonus?'<span>いっしょに +10</span>':''}</p>${newFriends.length?`<div class="befriend-row">${newFriends.map(k=>`<button class="befriend" data-befriend="${k}" aria-label="${esc(people[k].name)}さんを仲間に追加"><span class="avatar sprite s${people[k].avatar}"></span><span class="befriend-badge">${icon('plus')}</span><small>${esc(people[k].name)}</small></button>`).join('')}</div>`:''}${task&&!task.done?`<button class="primary" data-complete-task="${task.id}">タスクを完了にする</button><button class="textbtn closemodal" data-page="home">あとで</button>`:'<button class="primary closemodal" data-page="home">田んぼへ戻る</button>'}`)}
// 集中終了の合図：画面を見ていなくても気づけるように、振動・音・端末通知を出す
function prepareAlerts(){if(!state.settings.sound)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume?.()}catch{}}
function chime(){if(!audioCtx)return;try{const t=audioCtx.currentTime;[784,988,1175].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0.0001,t+i*.18);g.gain.exponentialRampToValueAtTime(.25,t+i*.18+.02);g.gain.exponentialRampToValueAtTime(.0001,t+i*.18+.5);o.connect(g).connect(audioCtx.destination);o.start(t+i*.18);o.stop(t+i*.18+.55)})}catch{}}
function alertDone(earned,task){if(state.settings.vibrate)navigator.vibrate?.([200,120,200]);if(state.settings.sound)chime();if(state.settings.notify&&document.hidden&&'Notification' in window&&Notification.permission==='granted'){try{new Notification('たんぼる',{body:`${earned}分の集中が終わりました${task?'：'+task.title:''}`,icon:'assets/icons/icon-192.png'})}catch{}}}
// 集中中は画面が消えないようにする（対応ブラウザのみ）
async function requestWakeLock(){try{if(running&&!wakeLock&&navigator.wakeLock&&!document.hidden){wakeLock=await navigator.wakeLock.request('screen');wakeLock.addEventListener('release',()=>{wakeLock=null})}}catch{wakeLock=null}}
