// ===== 作業場 =====
const hhmm=t=>new Date(t).toTimeString().slice(0,5);
function roomNow(t,now=Date.now()){const c=t.cycle*60000,o=t.offset*60000,startAt=Math.floor((now-o)/c)*c+o,endAt=startAt+t.minutes*60000;return {...t,startAt,endAt,live:now<endAt,left:Math.ceil((endAt-now)/60000),nextAt:startAt+c}}
// 自分の作業場に入ってきた人は、元の作業場からいなくなる
function liveRooms(now=Date.now()){const guestBusy=state.room?.mine&&now>=state.room.joinAt,guestKey=state.room?.mine?roomGuest(state.room)[0]:null;const night=skyKind()==='night';return roomTemplates.filter(t=>!(guestBusy&&(t.host===guestKey||t.members.some(m=>m[0]===guestKey)))&&!(t.dayOnly&&night)&&!(t.nightOnly&&!night)).map(t=>roomNow(t,now))}
function placeIcon(p){return icon(p===ONLINE?'online':'pin')}
function roomJoinable(r){return r.live&&r.left>=3&&r.members.length<r.capacity}
function roomMembers(room){return room.mine?(Date.now()>=room.joinAt?[roomGuest(room)]:[]):room.members}
