function taskOptions(){const id=focusTaskId();return state.tasks.filter(t=>!t.done).map(t=>`<option value="${t.id}" ${id===String(t.id)?'selected':''}>${esc(t.title)}</option>`).join('')+`<option value="" ${id===''?'selected':''}>自由に集中する</option>`}
const stamps=['がんばろう','いいね','あと少し','おつかれ'];
const selectArrow='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg>';
function renderRooms(){
 if(running&&state.room){const r=state.room,others=roomMembers(r),task=state.tasks.find(t=>String(t.id)===String(sessionTask));
  const now=Date.now(),guestComing=r.mine&&now<r.arriveAt,meStatus=r.mine||r.arrived?'集中中':'向かっています';
  return `<section class="card room-live"><div class="between"><span class="room-live-head"><span class="pill">${esc(roomName(r))}</span><span class="room-place-line">${placeIcon(r.place)}${esc(r.place||'')}</span>${r.mark?`<span class="room-mark">目印：${esc(r.mark)}</span>`:''}</span><button class="textbtn icon-btn" data-leave-room aria-label="作業場を出る" title="作業場を出る">${icon('exit')}</button></div>${r.place===ONLINE?'<span class="room-online-note">カメラなしで、同じ時間に集中中</span>':''}<div class="room-clock"><strong id="time">${timeText()}</strong><span>${esc(task?task.title:'自由に集中')}</span></div><ul class="room-members"><li><span class="room-member"><span class="avatar sprite s${state.profile.avatar}"></span><span><b>あなた</b><small>${meStatus}</small></span>${!r.mine&&!r.arrived?'<button class="primary arrived-btn" data-arrived>着いた</button>':''}</span></li>${others.map(([k,t])=>`<li><button data-cheer="${k}" aria-label="${esc(people[k].name)}さんに拍手を送る"><span class="avatar sprite s${people[k].avatar}"></span><span><b>${esc(people[k].name)}</b><small>${guestComing?(r.place===ONLINE?'もうすぐ入ります':'向かっています'):esc(t)}</small></span>${art('rice_mascot_happy','cheer','')}</button></li>`).join('')}</ul>${others.length?`<div class="room-stamps" aria-label="スタンプを送る">${stamps.map(t=>`<button data-stamp="${t}">${t}</button>`).join('')}</div>`:''}<div class="room-grow"><img id="roomRice" class="room-rice" src="${suppliedAssets[riceFor(r)]}" alt=""><small>集中するほど、稲がのびていく</small></div><p class="room-note">${others.length?'いっしょに終えると +10 pt ボーナス':'だれかが入ってくるのを待っています'}</p></section>`}
 const rooms=liveRooms().filter(roomJoinable);
 return `<section class="card room-create"><h2 class="sectiontitle">自分の作業場をひらく</h2><div class="room-select"><select id="roomTask" aria-label="取り組むタスク">${taskOptions()}</select>${selectArrow}</div><div class="room-select room-place">${placeIcon(state.roomPlace)}<select id="roomPlace" aria-label="集まる場所">${[...sfcPlaces,ONLINE].map(x=>`<option ${state.roomPlace===x?'selected':''}>${x}</option>`).join('')}</select>${selectArrow}</div>${state.roomPlace===ONLINE?'<p class="room-online-note">カメラなしで、同じ時間に集中します</p>':`<input id="roomMark" class="room-mark-input" maxlength="30" value="${esc(state.roomMark||'')}" placeholder="目印（例：窓側の席・青いパーカー）" aria-label="相手に見つけてもらう目印">`}<div class="room-times">${[15,25,50].map(n=>`<button data-room-duration="${n}" class="${duration===n&&!customTime?'selected':''}">${n}分</button>`).join('')}${customTime||![15,25,50].includes(duration)?`<label class="room-custom selected"><input id="roomMinutes" type="number" min="1" max="180" step="1" value="${duration}" aria-label="集中する時間（分）"><span>分</span></label>`:'<button data-room-custom>その他</button>'}<button class="primary icon-btn" data-open-room aria-label="作業場をひらいて集中する" title="ひらいて集中する">${icon('play')}</button></div></section><p class="search-count">いま集中している作業場</p><div class="room-list">${rooms.length?'':`<div class="search-empty">いま集中している人はいません。<br>自分の作業場をひらいてみよう</div>`}${rooms.map(r=>`<button class="card room-row" data-room="${r.key}"><span class="room-faces">${faces(r.members.map(m=>m[0]))}</span><span class="room-copy"><b>${esc(people[r.host].name)}の作業場</b><small>${esc(r.place)}</small><small class="room-status">あと${r.left}分</small></span><span class="room-count">${r.members.length} / ${r.capacity}</span>${icon('right')}</button>`).join('')}</div>`}
function quickFocus(){const r=state.room;if(running&&r)return `<section class="card quickfocus" data-go-rooms role="button" tabindex="0" aria-label="作業場を開く"><div><h2><span id="quicktime">${timeText()}</span> ${esc(roomName(r))}で集中中</h2></div><button class="primary icon-btn" data-page="friends" data-friend-view="rooms" aria-label="作業場を開く" title="作業場を開く">${icon('focus')}</button></section>`;const live=[...new Set(liveRooms().filter(roomJoinable).flatMap(r=>r.members.map(m=>m[0])))];return `<section class="card quickfocus" data-go-rooms role="button" tabindex="0" aria-label="作業場を見る"><div><h2>みんなと集中する</h2>${live.length?`<span class="quick-faces">${faces(live.slice(0,4))}<small>${live.length}人が集中中</small></span>`:''}</div><button class="primary icon-btn" data-page="friends" data-friend-view="rooms" aria-label="作業場を見る" title="作業場">${icon('focus')}</button></section>`}
function openRoom(key){const t=roomTemplates.find(t=>t.key===key);if(!t)return;if(running){page='friends';friendView='rooms';render();toast('いまの作業場を出てから入れます');return}const r=liveRooms().find(x=>x.key===key);if(!r){toast(people[t.host].name+'さんはいま別の作業場にいます');return}if(!roomJoinable(r)){toast(people[t.host].name+'さんはいま集中していません');return}modal(`<div class="room-detail"><span class="pill">${esc(r.type)}</span><h2>${esc(people[r.host].name)}の作業場</h2><p class="room-place-line">${placeIcon(r.place)}${esc(r.place)}</p>${r.mark?`<p class="room-mark">目印：${esc(r.mark)}</p>`:''}<p class="room-time">${esc(r.title)} · あと${r.left}分</p><ul class="room-members">${r.members.map(([k,task])=>`<li><button data-person="${k}"><span class="avatar sprite s${people[k].avatar}"></span><span><b>${esc(people[k].name)}</b><small>${esc(task)}</small></span></button></li>`).join('')}</ul>${`<label class="room-label" for="joinTask">取り組むタスク</label><div class="room-select"><select id="joinTask">${taskOptions()}</select>${selectArrow}</div><button class="primary" data-join-room="${key}">${r.place===ONLINE?'オンラインで参加する':'ここで合流して集中する'}</button>`}</div>`)}
function joinRoom(key){const r=liveRooms().find(x=>x.key===key);if(!r||!roomJoinable(r)||running){$('#modal').close();render();toast('この作業場にはいま入れません');return}startSession({mine:false,key,host:r.host,title:r.title,type:r.type,place:r.place,mark:r.mark,endAt:r.endAt,members:r.members,arrived:r.place===ONLINE},$('#joinTask')?.value??focusTaskId());toast(people[r.host].name+'さんの作業場に入りました')}
function openOwnRoom(){if(running)return;const n=Number($('#roomMinutes')?.value||duration);if(!Number.isInteger(n)||n<1||n>180){toast('1〜180分で入力してください');return}setDuration(n);const taskId=$('#roomTask')?.value??focusTaskId(),task=state.tasks.find(t=>String(t.id)===String(taskId)),now=Date.now();const place=$('#roomPlace')?.value||state.roomPlace,online=place===ONLINE,mark=online?'':($('#roomMark')?.value??state.roomMark??'').trim().slice(0,30);state.roomPlace=place;state.roomMark=mark;startSession({mine:true,host:'me',title:task?task.title:'自由に集中',type:'勉強',place,mark,guest:pickGuest(place),endAt:now+n*60000,joinAt:now+15000,arriveAt:online?now+15000:now+40000},taskId);toast('作業場をひらきました')}
function startSession(room,taskId){const now=Date.now();state.room={...room,joinedAt:now};running=true;deadline=room.endAt;remaining=Math.ceil((deadline-now)/1000);sessionId='room-'+now+'-'+Math.random().toString(36).slice(2);sessionTask=String(taskId);if(taskId!=='')state.focusTaskId=String(taskId);prepareAlerts();requestWakeLock();save();if($('#modal').open)$('#modal').close();page='friends';friendView='rooms';render()}
function focusedMinutes(){return state.room?Math.max(0,Math.floor((Math.min(Date.now(),state.room.endAt)-state.room.joinedAt)/60000)):0}
// 途中で出たときは、それまでの分を半分のポイント（1分=1pt）にする
function leaveRoom(){const m=focusedMinutes(),room=state.room,others=room?roomMembers(room).map(o=>o[0]):[],task=state.tasks.find(t=>String(t.id)===String(sessionTask));if(m>=1){state.points+=m;state.minutes+=m;if(task)task.focusMinutes=(task.focusMinutes||0)+m;if(others.length){state.recentTogether=[...new Set([...others,...state.recentTogether])].slice(0,6);state.roomHistory=[{at:Date.now(),place:room.place||'',minutes:m,task:task?.title||'',with:others,left:true},...state.roomHistory].slice(0,20)}}running=false;deadline=null;remaining=duration*60;sessionId=null;sessionTask=null;state.room=null;releaseWakeLock();save();$('#modal').close();render();toast(m>=1?`作業場を出ました（+${m} pt）`:'作業場を出ました')}
// 集中中のできごと：自分の作業場に人が入ってくる・途中で拍手が届く
function roomTick(){const r=state.room;if(!r)return;const now=Date.now();if(r.mine&&!r.joinNotified&&now>=r.joinAt){r.joinNotified=true;save();toast(people[roomGuest(r)[0]].name+(r.place===ONLINE?'さんがオンラインで入りました':'さんが作業場に向かっています'),'rice_mascot_happy');if(page==='friends'&&friendView==='rooms')render()}if(r.mine&&r.place!==ONLINE&&r.joinNotified&&!r.arriveNotified&&now>=r.arriveAt){r.arriveNotified=true;save();toast(people[roomGuest(r)[0]].name+'さんが着きました。目印で見つけてもらえました','rice_mascot_happy');if(page==='friends'&&friendView==='rooms'&&!$('#modal').open)render()}const others=roomMembers(r);if(!r.cheered&&others.length&&now>=r.joinedAt+(r.endAt-r.joinedAt)/2){r.cheered=true;save();toast(people[others[0][0]].name+'さんから「'+(Math.random()<.5?'いいね':'がんばろう')+'」','rice_mascot_happy')}const rice=$('#roomRice'),src=suppliedAssets[riceFor(r)];if(rice&&!rice.src.endsWith(src))rice.src=src}
function riceFor(r){const p=Math.max(0,Math.min(1,(Date.now()-r.joinedAt)/Math.max(1,r.endAt-r.joinedAt)));return 'rice_stage_0'+Math.min(6,1+Math.floor(p*6))}
function refreshRooms(){if(running||page!=='friends'&&page!=='home')return;const key=liveRooms().map(r=>r.key+r.live+r.left).join('|');if(key===roomsKey)return;roomsKey=key;if(!$('#modal').open&&(page==='home'||friendView==='rooms'))render()}

// ===== 天気と時間帯でホームの空を変える（SFC の現在の天気：Open-Meteo、登録不要） =====
const SFC_WEATHER_URL='https://api.open-meteo.com/v1/forecast?latitude=35.3881&longitude=139.4272&current=weather_code,is_day,temperature_2m&timezone=Asia%2FTokyo';
let skyShown='';
function freshWeather(){const w=state.weather;return w&&Date.now()-w.at<3*3600000?w:null}
function isWet(c){return (c>=51&&c<=67)||(c>=71&&c<=86)||c>=95}
function weatherLabel(c){return c<=1?'晴れ':c<=3?'くもり':c<=48?'霧':c<=57?'霧雨':c<=67?'雨':c<=77?'雪':c<=82?'にわか雨':c<=86?'雪':'雷雨'}
// 夜を優先（暗い時間は夜空）、昼は雨・雪なら雨の空、それ以外は晴れの空。天気が取れないときは時刻だけで判断
function skyKind(){const w=freshWeather(),h=new Date().getHours();if(w?!w.isDay:(h<6||h>=18))return 'night';return w&&isWet(w.code)?'rain':'clear'}
async function fetchWeather(){if(state.weather&&Date.now()-state.weather.at<30*60000)return;try{const res=await fetch(SFC_WEATHER_URL);if(!res.ok)return;const c=(await res.json()).current;if(!c||!Number.isFinite(c.weather_code))return;state.weather={at:Date.now(),code:c.weather_code,isDay:c.is_day===1,temp:Math.round(c.temperature_2m)};save();refreshSky(true)}catch{}}
function refreshSky(force){const k=skyKind()+(freshWeather()?.code??'');if(!force&&k===skyShown)return;const first=!skyShown;skyShown=k;if(!first&&page==='home'&&!$('#modal').open)render();else document.body.dataset.sky=skyKind();if(Date.now()-(state.weather?.at||0)>=30*60000)fetchWeather()}
fetchWeather();

// ===== 田んぼにときどき来る生きもの（カラス・イナゴ）。タップすると逃げていく =====
let visitorTimer=null,visitorBusy=false;
const vimg=n=>'assets/library/'+n+'.webp',pause=ms=>new Promise(r=>setTimeout(r,ms));
const glide=(el,frames,ms)=>el.animate(frames,{duration:ms,easing:'ease-in-out',fill:'forwards'}).finished.catch(()=>{});
function scheduleVisitor(first){clearTimeout(visitorTimer);visitorTimer=setTimeout(()=>{if(page==='home'&&!document.hidden&&!$('#modal').open&&!visitorBusy&&!window.matchMedia?.('(prefers-reduced-motion: reduce)').matches)spawnVisitor();scheduleVisitor(false)},first?8000+Math.random()*7000:60000+Math.random()*60000)}
function spawnVisitor(kind){const field=$('.supplied-field');if(!field||visitorBusy)return;kind ||= skyKind()==='night'||Math.random()<.4?'grasshopper':'crow';visitorBusy=true;const el=document.createElement('img');el.className='visitor visitor-'+kind;el.alt='';el.draggable=false;field.appendChild(el);(kind==='crow'?crowVisit(el):grasshopperVisit(el)).finally(()=>{el.remove();visitorBusy=false})}
async function crowVisit(el){let leaving=false;el.onclick=()=>{leaving=true};const flap=()=>setInterval(()=>{el.src=vimg(el.src.includes('crow_fly1')?'crow_fly2':'crow_fly1')},180),land={x:42+Math.random()*22,y:44+Math.random()*8};
 el.src=vimg('crow_fly1');let f=flap();await glide(el,[{left:'-25%',top:'6%'},{left:land.x+'%',top:land.y+'%'}],2400);clearInterval(f);if(!el.isConnected)return;
 el.src=vimg('crow_land');await pause(450);
 for(let i=0;i<9&&!leaving&&el.isConnected;i++){el.src=vimg(i%2?'crow_land':'crow_peck');await pause(450)}
 if(!el.isConnected)return;if(leaving)toast('カラスを追いはらいました');
 el.src=vimg('crow_fly1');f=flap();await glide(el,[{left:land.x+'%',top:land.y+'%'},{left:'125%',top:'-15%'}],leaving?1000:1900);clearInterval(f)}
async function grasshopperVisit(el){let leaving=false;el.onclick=()=>{leaving=true};const ground=58+Math.random()*6,target=24+Math.random()*30;let x=-15;
 const hop=async(to,ms)=>{el.src=vimg('grasshopper_jump');await glide(el,[{left:x+'%',top:ground+'%'},{left:(x+to)/2+'%',top:(ground-9)+'%'},{left:to+'%',top:ground+'%'}],ms);x=to;if(el.isConnected)el.src=vimg('grasshopper_stand')};
 el.style.left=x+'%';el.style.top=ground+'%';el.src=vimg('grasshopper_stand');
 while(x<target-1&&el.isConnected){await hop(Math.min(target,x+18),650);await pause(350)}
 for(let i=0;i<12&&!leaving&&el.isConnected;i++)await pause(400);
 if(!el.isConnected)return;if(leaving)toast('イナゴがぴょんと逃げていきました');
 while(x<115&&el.isConnected){await hop(x+22,leaving?420:650);await pause(leaving?60:250)}}
scheduleVisitor(true);

// ===== つながりマップ：真ん中の「あなた」から、いっしょに集中した人へ水路がのびる。回数が多いほど水路が太い =====
// 人数に合わせて「あなた」のまわりへ均等に並べる（上から時計回り）
const mapSlot=(i,n)=>{const a=-Math.PI/2+(n===2?Math.PI/2:0)+i*2*Math.PI/n;return [50+Math.cos(a)*34,50+Math.sin(a)*32]},MAP_MAX=6;
function togetherStats(){const st={};state.roomHistory.forEach(h=>h.with.forEach(k=>{st[k] ||= {count:0,minutes:0};st[k].count++;st[k].minutes+=h.minutes}));return st}
function roomOf(k){const live=liveRooms().filter(roomJoinable);return live.find(t=>t.host===k)||live.find(t=>t.members.some(m=>m[0]===k))}
function renderMap(){
 const st=togetherStats(),all=[...new Set([...state.connections,...Object.keys(st),...state.recentTogether])].filter(k=>people[k]).sort((a,b)=>(st[b]?.count||0)-(st[a]?.count||0)),keys=all.slice(0,all.length>MAP_MAX?MAP_MAX-1:MAP_MAX),rest=all.slice(keys.length);
 if(!keys.includes(mapSelected))mapSelected=keys[0]||null;
 const C=[50,50],stream=(k,[x,y])=>{const dx=x-C[0],dy=y-C[1],len=Math.hypot(dx,dy),nx=-dy/len*7,ny=dx/len*7,c1=[C[0]+dx*.35+nx,C[1]+dy*.35+ny],c2=[C[0]+dx*.68-nx,C[1]+dy*.68-ny],d=`M${C} C${c1} ${c2} ${x},${y}`,friend=state.connections.includes(k),w=Math.min(22,10+(st[k]?.count||0)*3);return `<path d="${d}" class="map-stream ${friend?'':'pending'}" style="stroke-width:${friend?w:6}px"/>${friend?`<path d="${d}" class="map-shine"/>`:''}`};
 const slots=keys.length+(rest.length?1:0);const nodes=keys.map((k,i)=>{const [x,y]=mapSlot(i,slots),p=people[k],n=st[k]?.count||0,friend=state.connections.includes(k);return `<button class="map-node ${friend?'':'pending'} ${mapSelected===k?'selected':''}" style="left:${x}%;top:${y}%" data-map-person="${k}" aria-label="${esc(p.name)}${n?'、いっしょに'+n+'回':''}${friend?'':'（まだ仲間ではありません）'}"><span class="map-blob"><span class="avatar sprite s${p.avatar}"></span>${n?`<span class="map-count">${n}回</span>`:''}</span><b>${esc(p.name)}</b></button>`}).join('');
 const deco=keys.map((k,i)=>{const [x,y]=mapSlot(i,slots),mx=(x+C[0])/2,my=(y+C[1])/2;return `<span class="map-sprig" style="left:${mx+(i%2?6:-6)}%;top:${my-4}%"></span><span class="map-dot" style="left:${mx+(i%2?-5:5)}%;top:${my+5}%"></span>`}).join('');
 const sel=mapSelected&&people[mapSelected],s0=sel&&st[mapSelected],friend=sel&&state.connections.includes(mapSelected),room=sel&&roomOf(mapSelected);
 const detail=sel?`<section class="card map-detail"><span class="avatar sprite s${sel.avatar}"></span><button class="map-detail-copy" data-map-history="${mapSelected}" aria-label="${esc(sel.name)}さん（${esc(sel.year)}）との記録を見る"><b>${esc(sel.name)}<span class="map-year">${esc(sel.year)}</span></b><small>${s0?`一緒に${s0.count}回・${s0.minutes}分`:`${esc(sel.department)} · ${esc(sel.year)}`} ›</small></button>${friend?(room&&!running?`<span class="map-now live">いま集中中</span><button class="primary" data-room="${room.key}">一緒に集中</button>`:`<span class="map-now">${running?'あなたが集中中':'いまは休憩中'}</span>`):`<button class="primary icon-btn map-add" data-connect="${mapSelected}" aria-label="${esc(sel.name)}さんを仲間に追加" title="仲間に追加">${icon('plus')}</button>`}</section>`:'';
 return `<section class="card map-card"><div class="map-head"><div><h2>つながりマップ</h2><p>${keys.length?`いっしょに集中した仲間 ${state.connections.length}人`:'作業場でいっしょに集中すると、ここに水路がのびていきます'}</p></div><span class="map-total">${icon('friends')}${state.connections.length}</span></div><div class="map-area"><svg class="map-streams" viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">${keys.map((k,i)=>stream(k,mapSlot(i,slots))).join('')}</svg>${deco}<button class="map-node me" style="left:50%;top:50%" data-page="profile" aria-label="マイページを開く"><span class="map-blob"><span class="avatar sprite s${state.profile.avatar}"></span></span><b>あなた</b></button>${nodes}${rest.length?(()=>{const [x,y]=mapSlot(keys.length,slots);return `<button class="map-node more" style="left:${x}%;top:${y}%" data-map-more aria-label="ほか${rest.length}人を見る"><span class="map-blob">+${rest.length}</span><b>ほか${rest.length}人</b></button>`})():''}</div>${keys.length?'':'<button class="primary map-empty-btn" data-friend-view="rooms">作業場をさがす</button>'}</section>${detail}`}
// 人ごとの「いっしょに集中した記録」（つながりマップで人を押したとき）
function openTogetherHistory(k){const p=people[k];if(!p)return;const list=state.roomHistory.filter(h=>h.with.includes(k));modal(`<div class="together-history"><span class="avatar sprite s${p.avatar}"></span><h2>${esc(p.name)}さんとの記録</h2><p class="settings-hint">${esc(p.department)} · ${esc(p.year)}</p>${list.length?`<ul>${list.map(h=>`<li><div class="history-top"><b>${new Date(h.at).toLocaleDateString('ja-JP',{month:'numeric',day:'numeric',weekday:'short'})} ${hhmm(h.at)}</b><span>${h.minutes}分${h.left?'（途中まで）':''}</span></div><p class="room-place-line">${placeIcon(h.place)}${esc(h.place||'')}</p><small>${esc(h.task||'自由に集中')}</small></li>`).join('')}</ul>`:'<p>まだいっしょに集中した記録はありません。</p>'}${state.connections.includes(k)?'':`<button class="primary icon-btn map-add" data-connect="${k}" aria-label="${esc(p.name)}さんを仲間に追加" title="仲間に追加">${icon('plus')}</button>`}</div>`)}
// ポップアップの外側を押したら閉じる
$('#modal').addEventListener('click',e=>{if(e.target!==e.currentTarget)return;const r=e.currentTarget.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.currentTarget.close()});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches?.('[data-go-rooms]')){e.preventDefault();page='friends';friendView='rooms';render()}});
// マップに入りきらない人の一覧
function openMapList(){const st=togetherStats(),all=[...new Set([...state.connections,...Object.keys(st),...state.recentTogether])].filter(k=>people[k]).sort((a,b)=>(st[b]?.count||0)-(st[a]?.count||0));modal(`<div class="together-history"><h2>つながっている人</h2><ul>${all.map(k=>`<li><button class="map-list-row" data-map-person="${k}" data-close-modal><span class="avatar sprite s${people[k].avatar}"></span><span><b>${esc(people[k].name)}<span class="map-year">${esc(people[k].year)}</span></b><small>${st[k]?`一緒に${st[k].count}回・${st[k].minutes}分`:esc(people[k].department)}</small></span></button></li>`).join('')}</ul></div>`)}
